{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":31089,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [markdown]\n# # **Simple 3D Gaussian Splatting Renderer**\n\n# %% [code]\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.patches import Ellipse\nimport cv2\nfrom typing import List, Tuple\nimport math\n\n# %% [markdown]\n# \n# \n# ---\n# \n# ### 🧩 `Gaussian3D`\n# \n# A class representing a **single 3D Gaussian blob** in the scene.\n# \n# * `position`: 3D location of the Gaussian (x, y, z).\n# * `scale`: The size of the Gaussian along x, y, and z axes.\n# * `rotation`: A quaternion `[w, x, y, z]` that defines the orientation.\n# * `color`: RGB color vector (values between 0 and 1).\n# * `opacity`: Transparency (0 = fully transparent, 1 = fully opaque).\n# \n# ---\n# \n# ### 🎨 `GaussianSplattingRenderer`\n# \n# A class that manages and renders a collection of 3D Gaussians onto a 2D image.\n# \n# #### Key Methods:\n# \n# * **`add_gaussian(...)`**\n#   Adds a new `Gaussian3D` object to the scene.\n# \n# * **`create_sample_scene()`**\n#   Creates a test scene with 5 colored Gaussians at different positions and sizes.\n# \n# * **`quaternion_to_rotation_matrix(q)`**\n#   Converts a rotation quaternion into a 3×3 rotation matrix for applying rotation to the Gaussian ellipsoid.\n# \n# * **`project_to_2d(...)`**\n#   Performs **simple perspective projection** of a 3D point to 2D screen coordinates using a pinhole camera model.\n# \n# * **`compute_2d_covariance(...)`**\n#   Calculates how the 3D Gaussian should appear (its shape and size) when projected onto the 2D image plane, taking into account scale, rotation, and depth.\n# \n# * **`render_gaussian_2d(...)`**\n#   Renders an individual 3D Gaussian blob onto the 2D image as a 2D elliptical Gaussian, using alpha blending to handle transparency.\n# \n# * **`render(...)`**\n#   The main rendering function. It:\n# \n#   1. Creates a blank image.\n#   2. Sorts Gaussians back-to-front based on depth.\n#   3. Renders each one to the image with proper blending.\n# \n# ---\n# \n# \n\n# %% [code]\nclass Gaussian3D:\n    \"\"\"3D Gaussian representation\"\"\"\n    def __init__(self, position: np.ndarray, scale: np.ndarray, rotation: np.ndarray, \n                 color: np.ndarray, opacity: float):\n        self.position = position  # 3D position [x, y, z]\n        self.scale = scale        # 3D scale [sx, sy, sz]\n        self.rotation = rotation  # Rotation quaternion [w, x, y, z]\n        self.color = color        # RGB color [r, g, b]\n        self.opacity = opacity    # Opacity value [0, 1]\n\nclass GaussianSplattingRenderer:\n    \"\"\"Simple 3D Gaussian Splatting Renderer\"\"\"\n    \n    def __init__(self, width: int = 800, height: int = 600):\n        self.width = width\n        self.height = height\n        self.gaussians = []\n        \n    def add_gaussian(self, gaussian: Gaussian3D):\n        \"\"\"Add a 3D Gaussian to the scene\"\"\"\n        self.gaussians.append(gaussian)\n        \n    def create_sample_scene(self):\n        \"\"\"Create a sample scene with multiple Gaussians\"\"\"\n        # Clear existing gaussians\n        self.gaussians = []\n        \n        # Add some sample Gaussians\n        positions = [\n            np.array([0.0, 0.0, -5.0]),\n            np.array([1.0, 0.5, -4.0]),\n            np.array([-1.0, -0.5, -6.0]),\n            np.array([0.5, -1.0, -3.5]),\n            np.array([-0.5, 1.0, -4.5]),\n        ]\n        \n        colors = [\n            np.array([1.0, 0.0, 0.0]),  # Red\n            np.array([0.0, 1.0, 0.0]),  # Green\n            np.array([0.0, 0.0, 1.0]),  # Blue\n            np.array([1.0, 1.0, 0.0]),  # Yellow\n            np.array([1.0, 0.0, 1.0]),  # Magenta\n        ]\n        \n        for i, (pos, color) in enumerate(zip(positions, colors)):\n            scale = np.array([0.3, 0.3, 0.3]) + np.random.normal(0, 0.1, 3)\n            rotation = np.array([1.0, 0.0, 0.0, 0.0])  # Identity quaternion\n            opacity = 0.8\n            \n            gaussian = Gaussian3D(pos, scale, rotation, color, opacity)\n            self.add_gaussian(gaussian)\n    \n    def quaternion_to_rotation_matrix(self, q: np.ndarray) -> np.ndarray:\n        \"\"\"Convert quaternion to rotation matrix\"\"\"\n        w, x, y, z = q\n        return np.array([\n            [1 - 2*y*y - 2*z*z, 2*x*y - 2*z*w, 2*x*z + 2*y*w],\n            [2*x*y + 2*z*w, 1 - 2*x*x - 2*z*z, 2*y*z - 2*x*w],\n            [2*x*z - 2*y*w, 2*y*z + 2*x*w, 1 - 2*x*x - 2*y*y]\n        ])\n    \n    def project_to_2d(self, point_3d: np.ndarray, \n                     camera_pos: np.ndarray = np.array([0, 0, 0]),\n                     focal_length: float = 500.0) -> Tuple[float, float]:\n        \"\"\"Project 3D point to 2D screen coordinates\"\"\"\n        # Simple perspective projection\n        relative_pos = point_3d - camera_pos\n        x_2d = (relative_pos[0] * focal_length) / abs(relative_pos[2]) + self.width / 2\n        y_2d = (relative_pos[1] * focal_length) / abs(relative_pos[2]) + self.height / 2\n        return x_2d, y_2d\n    \n    def compute_2d_covariance(self, gaussian: Gaussian3D, \n                            camera_pos: np.ndarray = np.array([0, 0, 0]),\n                            focal_length: float = 500.0) -> np.ndarray:\n        \"\"\"Compute 2D covariance matrix for projection\"\"\"\n        # Get rotation matrix\n        R = self.quaternion_to_rotation_matrix(gaussian.rotation)\n        \n        # Create 3D covariance matrix\n        S = np.diag(gaussian.scale ** 2)\n        cov_3d = R @ S @ R.T\n        \n        # Simple approximation for 2D projection\n        # In practice, this would involve Jacobian of projection\n        z_dist = abs(gaussian.position[2] - camera_pos[2])\n        scale_factor = focal_length / z_dist\n        \n        # Project to 2D (simplified)\n        cov_2d = np.array([\n            [cov_3d[0, 0] * scale_factor**2, cov_3d[0, 1] * scale_factor**2],\n            [cov_3d[1, 0] * scale_factor**2, cov_3d[1, 1] * scale_factor**2]\n        ])\n        \n        return cov_2d\n    \n    def render_gaussian_2d(self, image: np.ndarray, gaussian: Gaussian3D,\n                          camera_pos: np.ndarray = np.array([0, 0, 0]),\n                          focal_length: float = 500.0):\n        \"\"\"Render a single gaussian to the image\"\"\"\n        # Project center to 2D\n        x_2d, y_2d = self.project_to_2d(gaussian.position, camera_pos, focal_length)\n        \n        # Skip if outside image bounds\n        if x_2d < 0 or x_2d >= self.width or y_2d < 0 or y_2d >= self.height:\n            return\n            \n        # Compute 2D covariance\n        cov_2d = self.compute_2d_covariance(gaussian, camera_pos, focal_length)\n        \n        # Add small regularization to avoid singular matrix\n        cov_2d += np.eye(2) * 1e-6\n        \n        try:\n            # Compute Gaussian parameters\n            det_cov = np.linalg.det(cov_2d)\n            if det_cov <= 0:\n                return\n                \n            inv_cov = np.linalg.inv(cov_2d)\n            \n            # Define rendering radius (3 sigma)\n            eigenvals, _ = np.linalg.eigh(cov_2d)\n            max_radius = int(3 * np.sqrt(max(eigenvals))) + 1\n            \n            # Render gaussian in local region\n            y_min = max(0, int(y_2d - max_radius))\n            y_max = min(self.height, int(y_2d + max_radius))\n            x_min = max(0, int(x_2d - max_radius))\n            x_max = min(self.width, int(x_2d + max_radius))\n            \n            for y in range(y_min, y_max):\n                for x in range(x_min, x_max):\n                    # Compute distance from center\n                    dx = x - x_2d\n                    dy = y - y_2d\n                    d = np.array([dx, dy])\n                    \n                    # Compute Gaussian value\n                    mahalanobis = d.T @ inv_cov @ d\n                    gaussian_val = np.exp(-0.5 * mahalanobis)\n                    \n                    # Alpha blending\n                    alpha = gaussian.opacity * gaussian_val\n                    alpha = np.clip(alpha, 0, 1)\n                    \n                    # Blend colors\n                    for c in range(3):\n                        image[y, x, c] = (1 - alpha) * image[y, x, c] + alpha * gaussian.color[c]\n                        \n        except np.linalg.LinAlgError:\n            # Skip if matrix operations fail\n            pass\n    \n    def render(self, camera_pos: np.ndarray = np.array([0, 0, 0]),\n               focal_length: float = 500.0, background_color: np.ndarray = np.array([0, 0, 0])) -> np.ndarray:\n        \"\"\"Render the scene\"\"\"\n        # Initialize image\n        image = np.full((self.height, self.width, 3), background_color, dtype=np.float32)\n        \n        # Sort gaussians by depth (back to front)\n        gaussians_with_depth = []\n        for gaussian in self.gaussians:\n            depth = np.linalg.norm(gaussian.position - camera_pos)\n            gaussians_with_depth.append((depth, gaussian))\n        \n        # Sort by depth (farthest first)\n        gaussians_with_depth.sort(key=lambda x: x[0], reverse=True)\n        \n        # Render each gaussian\n        for depth, gaussian in gaussians_with_depth:\n            self.render_gaussian_2d(image, gaussian, camera_pos, focal_length)\n        \n        return np.clip(image, 0, 1)\n\n# %% [markdown]\n# \n# ---\n# \n# ### 🎯 **Purpose**\n# \n# The function demonstrates how to:\n# \n# * Create a scene with multiple 3D Gaussians\n# * Render the scene from different camera viewpoints\n# * Generate an animated video of the scene rotating around the object\n# \n# ---\n# \n# ### 🔍 **Step-by-step Breakdown**\n# \n# #### 1. **Initialize Renderer and Scene**\n# \n# ```python\n# renderer = GaussianSplattingRenderer(width=800, height=600)\n# renderer.create_sample_scene()\n# ```\n# \n# Creates a renderer and populates it with five sample Gaussians of different colors and positions.\n# \n# #### 2. **Render Static Views**\n# \n# ```python\n# viewpoints = [np.array([...]), ...]\n# fig, axes = plt.subplots(...)\n# ```\n# \n# * Defines four camera positions (front, side, top, etc.)\n# * Renders a static image from each viewpoint\n# * Displays them using matplotlib in a 2×2 subplot\n# \n# #### 3. **Animated Rotation Rendering**\n# \n# ```python\n# angles = np.linspace(0, 2*np.pi, num_frames)\n# for angle in angles:\n#     camera_pos = [...]\n#     rendered_image = renderer.render(...)\n# ```\n# \n# * Simulates a rotating camera around the scene\n# * At each frame, renders a 2D image from a new camera position\n# * Collects each frame into a list\n# \n# #### 4. **Video Export**\n# \n# ```python\n# import imageio\n# imageio.mimwrite('video.mp4', frames, ...)\n# ```\n# \n# * Converts the rendered frames into a `.mp4` video using `imageio`\n# \n# #### 5. **Jupyter Notebook Display (Optional)**\n# \n# ```python\n# from IPython.display import HTML\n# ```\n# \n# * If run inside a Jupyter notebook, displays the video inline\n# * Falls back to saving `video.mp4` if not in notebook environment\n# \n# ---\n# \n# ### ✅ **Outputs**\n# \n# * Static renders from 4 viewpoints (shown with matplotlib)\n# * A rotating animation of the scene saved as `video.mp4`\n# * Optional video display in Jupyter\n# \n# ---\n# \n\n# %% [code]\ndef main():\n    \"\"\"Main function to demonstrate Gaussian Splatting\"\"\"\n    # Create renderer\n    renderer = GaussianSplattingRenderer(width=800, height=600)\n    \n    # Create sample scene\n    renderer.create_sample_scene()\n    \n    print(f\"Created scene with {len(renderer.gaussians)} Gaussians\")\n    \n    # Render from different viewpoints\n    viewpoints = [\n        np.array([0, 0, 0]),      # Front view\n        np.array([2, 1, 0]),      # Right-up view\n        np.array([-1, 0, 2]),     # Left-back view\n        np.array([0, 2, 1]),      # Top view\n    ]\n    \n    view_names = [\"Front View\", \"Right-Up View\", \"Left-Back View\", \"Top View\"]\n    \n    # Create subplot for multiple views\n    fig, axes = plt.subplots(2, 2, figsize=(12, 9))\n    axes = axes.flatten()\n    \n    for i, (camera_pos, view_name) in enumerate(zip(viewpoints, view_names)):\n        print(f\"Rendering {view_name}...\")\n        \n        # Render the scene\n        rendered_image = renderer.render(\n            camera_pos=camera_pos,\n            focal_length=600.0,\n            background_color=np.array([0.1, 0.1, 0.2])  # Dark blue background\n        )\n        \n        # Display the result\n        axes[i].imshow(rendered_image)\n        axes[i].set_title(view_name)\n        axes[i].axis('off')\n    \n    plt.tight_layout()\n    plt.suptitle(\"3D Gaussian Splatting - Multiple Views\", fontsize=16, y=0.98)\n    plt.show()\n    \n    # Create animated rotation and save frames\n    print(\"Creating animated rotation and saving frames...\")\n    \n    # Create rotation sequence\n    num_frames = 36\n    angles = np.linspace(0, 2*np.pi, num_frames)\n    frames = []\n    \n    for i, angle in enumerate(angles):\n        print(f\"Rendering frame {i+1}/{num_frames}...\")\n        \n        # Circular camera movement\n        radius = 3.0\n        camera_pos = np.array([\n            radius * np.cos(angle),\n            0.5 * np.sin(2 * angle),  # Add some vertical movement\n            radius * np.sin(angle)\n        ])\n        \n        # Render\n        rendered_image = renderer.render(\n            camera_pos=camera_pos,\n            focal_length=600.0,\n            background_color=np.array([0.05, 0.05, 0.15])\n        )\n        \n        # Convert to uint8 format for video\n        frame = (rendered_image * 255).astype(np.uint8)\n        frames.append(frame)\n    \n    # Create video using imageio\n    print(\"Creating video...\")\n    import imageio\n    f = 'video.mp4'\n    imageio.mimwrite(f, frames, fps=3, quality=10)\n    print(f\"Video saved as {f}\")\n\n    print(\"Rendering complete!\")\n    print(\"\\nScene Statistics:\")\n    print(f\"- Image resolution: {renderer.width}x{renderer.height}\")\n    print(f\"- Number of Gaussians: {len(renderer.gaussians)}\")\n    print(f\"- Rendering method: CPU-based rasterization\")\n\nif __name__ == \"__main__\":\n    main()\n\n# %% [code]\nfrom IPython.display import HTML\nfrom base64 import b64encode\n\nmp4 = open('video.mp4','rb').read()\ndata_url = \"data:video/mp4;base64,\" + b64encode(mp4).decode()\nHTML(\"\"\"\n<video width=500 controls autoplay loop>\n      <source src=\"%s\" type=\"video/mp4\">\n</video>\n\"\"\" % data_url)\n\n# %% [code]\n\n\n# %% [markdown]\n# ","metadata":{"_uuid":"0f624fa3-265f-4acd-86c3-d2ae245e9922","_cell_guid":"24a699ad-f16f-4121-83e8-b625c52b6cee","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}